CREATE TABLE `universities` (
  `id` int NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `country` varchar(100) NOT NULL,
  `city` varchar(100) NOT NULL,
  `course` varchar(255) NOT NULL,
  `subject` varchar(100) NOT NULL,
  `ranking` int DEFAULT NULL,
  `fees_per_year` int DEFAULT NULL,
  `university_type` varchar(50) NOT NULL,
  `scholarships` tinyint(1) NOT NULL DEFAULT '0',
  `entry_requirements` text NOT NULL,
  `about` text NOT NULL,
  `website` varchar(500) DEFAULT NULL,
  `tags` json DEFAULT NULL,
  `strengths` json DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `courses` json DEFAULT NULL,
  `rankings` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_universities_slug` (`slug`),
  KEY `ix_universities_subject` (`subject`),
  KEY `ix_universities_country` (`country`),
  KEY `ix_universities_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=1912 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
