INSERT INTO `universities` VALUES (1,'stanford-computer-science','Stanford University','United States of America','Palo Alto','Computer Science','computer-science',1,62000,'private',1,'Top grades (A/A*), strong SAT/ACT, compelling essays, demonstrated interest in CS/AI, extracurricular depth.','The heart of Silicon Valley\'s startup culture. World-leading AI (Google DeepMind roots, ChatGPT alumni), incredible research and an unmatched founder ecosystem.','https://www.stanford.edu','[\"ai\", \"ml\", \"startups\", \"entrepreneurship\", \"research\"]','[\"#1 for AI & CS research\", \"Unmatched startup culture\", \"Massive alumni network in tech\"]','2026-09-12 20:16:38','[\"Architecture & Built Environment\", \"Computer Science & Information Systems\", \"Data Science & Artificial Intelligence\", \"Law\", \"Marketing\", \"Materials Science\", \"Social Policy & Administration\", \"Sociology\", \"Statistics & Operational Research\", \"Veterinary Science\"]','{\"law\": 5, \"arts\": 3, \"science\": 1, \"business\": 2, \"medicine\": 3, \"economics\": 3, \"engineering\": 2, \"architecture\": 28, \"data-science\": 2, \"computer-science\": 2}'),(2,'mit-eecs','MIT','United States of America','Cambridge','Electrical Engineering & Computer Science','computer-science',1,60000,'private',1,'Exceptional academics and SAT/ACT, standout projects, strong math olympiad/competition record.','The world\'s most rigorous engineering school. Famous for hands-on learning, competitions, and an unmatched brand in tech recruiting.','https://web.mit.edu','[\"engineering\", \"robotics\", \"math\", \"research\"]','[\"#1 globally in several engineering fields\", \"Hands-on \'mens et manus\' culture\", \"Elite technology brand\"]','2026-09-12 20:16:38','[\"Architecture & Built Environment\", \"Computer Science & Information Systems\", \"Data Science & Artificial Intelligence\", \"Marketing\", \"Materials Science\", \"Social Policy & Administration\", \"Sociology\", \"Statistics & Operational Research\", \"Veterinary Science\"]','{\"arts\": 1, \"science\": 1, \"business\": 2, \"medicine\": 16, \"economics\": 2, \"engineering\": 1, \"architecture\": 2, \"data-science\": 1, \"computer-science\": 1}'),(3,'uc-berkeley-eecs','UC Berkeley','United States of America','Berkeley','Electrical Engineering & Computer Science','computer-science',3,44000,'public',1,'Strong GPA, SAT/ACT, essays; emphasis on demonstrated interest in CS and contributions to community.','One of the strongest public universities in the world for CS — right next to Silicon Valley, with deep AI/ML roots.','https://www.berkeley.edu','[\"ai\", \"cs\", \"public\", \"silicon valley\"]','[\"Top-5 CS program\", \"Adjacent to the Bay Area tech industry\", \"Strong AI & systems research\"]','2026-09-12 20:16:38','[\"Architecture & Built Environment\", \"Computer Science & Information Systems\", \"Data Science & Artificial Intelligence\", \"Law\", \"Marketing\", \"Materials Science\", \"Social Policy & Administration\", \"Sociology\", \"Statistics & Operational Research\", \"Veterinary Science\"]','{\"law\": 10, \"arts\": 4, \"science\": 4, \"business\": 9, \"medicine\": 45, \"economics\": 7, \"engineering\": 3, \"architecture\": 10, \"data-science\": 6, \"computer-science\": 6}'),(4,'harvard-computer-science','Harvard University','United States of America','Cambridge (MA)','Computer Science','computer-science',1,59000,'private',1,'Outstanding academics, SAT/ACT, essays and recommendations; leadership and impact important.','A brand like no other. CS at Harvard combines elite teaching with a powerful global network — and generous financial aid.','https://www.harvard.edu','[\"cs\", \"leadership\", \"brand\", \"finance\"]','[\"World-famous brand & network\", \"Strong CS + interdisciplinary options\", \"Excellent need-based aid\"]','2026-09-12 20:16:38','[\"Architecture & Built Environment\", \"Computer Science & Information Systems\", \"Data Science & Artificial Intelligence\", \"Law\", \"Marketing\", \"Materials Science\", \"Social Policy & Administration\", \"Sociology\", \"Statistics & Operational Research\", \"Veterinary Science\"]','{\"law\": 1, \"arts\": 1, \"science\": 1, \"business\": 1, \"medicine\": 1, \"economics\": 1, \"engineering\": 6, \"architecture\": 7, \"data-science\": 8, \"computer-science\": 7}'),(5,'oxford-computer-science','University of Oxford','United Kingdom','Oxford','Computer Science','computer-science',1,48000,'public',1,'A* in Maths + A in further subjects, exceptional aptitude in problem solving (interview-based admissions).','800 years of academic excellence. Small tutorial teaching, rigorous mathematics and deep theory in CS.','https://www.ox.ac.uk','[\"theory\", \"mathematics\", \"tutorials\", \"uk\"]','[\"Tutorial-style teaching\", \"World-class theory & mathematics\", \"Historic global reputation\"]','2026-09-12 20:16:38','[\"Architecture & Built Environment\", \"Computer Science & Information Systems\", \"Data Science & Artificial Intelligence\", \"Law\", \"Marketing\", \"Materials Science\", \"Social Policy & Administration\", \"Sociology\", \"Statistics & Operational Research\", \"Veterinary Science\"]','{\"law\": 2, \"arts\": 1, \"science\": 1, \"business\": 4, \"medicine\": 2, \"economics\": 2, \"engineering\": 7, \"architecture\": 42, \"data-science\": 6, \"computer-science\": 4}'),(6,'imperial-college-computing','Imperial College London','United Kingdom','London','Computing','computer-science',4,45000,'public',1,'Strong A-levels (A*A*A) with Maths, high admissions test performance, coding aptitude.','Science-focused powerhouse in London with excellent placement rates and strong industry links in Europe\'s biggest tech hub.','https://www.imperial.ac.uk','[\"engineering\", \"london\", \"placement\", \"uk\"]','[\"Elite engineering reputation\", \"Exceptional employment outcomes\", \"Central London tech scene\"]','2026-09-12 20:16:38','[\"Computer Science & Information Systems\", \"Data Science & Artificial Intelligence\", \"Marketing